ext('c12_eng_ch8',[
C("📰","प्रेस की भूमिका लोकतंत्र में",["सूचना देना","जनता की आवाज़ उठाना","सरकार पर नज़र रखना","लोकतंत्र का चौथा स्तंभ"],"प्रेस को लोकतंत्र का चौथा स्तंभ कहा जाता है, विधायिका, कार्यपालिका और न्यायपालिका के बाद। उसका काम जनता तक सही सूचना पहुँचाना, सरकार के कामों पर नज़र रखना और जनता की समस्याओं को उठाना है। अगर प्रेस स्वतंत्र न हो, तो लोगों को सच का पता ही नहीं चलेगा और सत्ता मनमानी कर सकती है। इसलिए स्वतंत्र प्रेस को स्वस्थ लोकतंत्र की पहचान माना जाता है।"),
Q("प्रेस को लोकतंत्र का चौथा स्तंभ क्यों कहा जाता है?","क्योंकि वह जनता को सूचित करता है और सरकार की निगरानी करके लोकतंत्र को मज़बूत बनाता है","सोचिए... तीन स्तंभ सरकार के अंग हैं। प्रेस जनता और सरकार के बीच की कड़ी है, जो सच सामने लाता है और जवाबदेही तय करता है। इसलिए उसे चौथा स्तंभ कहते हैं।"),
C("🏛️","संविधान और अभिव्यक्ति की स्वतंत्रता",["अनुच्छेद 19(1)(क)","प्रेस की अलग से व्याख्या नहीं","उचित प्रतिबंध","सर्वोच्च न्यायालय की भूमिका"],"भारत के संविधान में प्रेस की स्वतंत्रता अलग से नहीं लिखी, पर वह अनुच्छेद उन्नीस के अंतर्गत अभिव्यक्ति की स्वतंत्रता में शामिल मानी जाती है। इस स्वतंत्रता पर राष्ट्र की सुरक्षा, सार्वजनिक व्यवस्था और मानहानि जैसे उचित प्रतिबंध भी लगाए जा सकते हैं। सर्वोच्च न्यायालय ने कई फ़ैसलों में प्रेस की स्वतंत्रता की रक्षा की है। यानी स्वतंत्रता के साथ ज़िम्मेदारी जुड़ी हुई है।"),
Q("भारत में प्रेस की स्वतंत्रता संविधान के किस अधिकार से जुड़ी है?","अभिव्यक्ति की स्वतंत्रता (अनुच्छेद 19)","अधिकार याद कीजिए... प्रेस की स्वतंत्रता अलग अधिकार नहीं, बल्कि अनुच्छेद उन्नीस में दी गई वाक् और अभिव्यक्ति की स्वतंत्रता का हिस्सा है। उस पर उचित प्रतिबंध भी लगते हैं।"),
C("⛓️","प्रेस पर दबाव के रूप",["सरकारी दबाव और सेंसरशिप","विज्ञापन देने वालों का प्रभाव","मालिकों के निहित स्वार्थ","धमकी और हिंसा"],"प्रेस पर कई तरह के दबाव आते हैं। सरकार सेंसरशिप या विज्ञापन रोककर अख़बार पर दबाव डाल सकती है। विज्ञापनदाता कंपनियाँ ऐसी ख़बरें दबवा देती हैं जो उन्हें असुविधाजनक लगें। अख़बार के मालिक अपने व्यावसायिक या राजनीतिक हित के लिए ख़बरें प्रभावित कर सकते हैं। कई बार पत्रकारों को धमकियाँ मिलती हैं और उनके साथ हिंसा भी होती है। ऐसे में निर्भीक और निष्पक्ष पत्रकारिता कठिन हो जाती है।"),
Q("प्रेस पर दबाव के दो स्रोत बताइए।","सरकार और विज्ञापनदाता (या मालिकों के निहित स्वार्थ)","स्रोत सोचिए... सरकार सेंसरशिप या विज्ञापन रोककर और विज्ञापन देने वाली कंपनियाँ अपना पैसा रोककर दबाव डाल सकती हैं। इन्हीं दबावों से प्रेस की स्वतंत्रता प्रभावित होती है।"),
C("🕵️","पत्रकार की नैतिक ज़िम्मेदारी",["सत्य की पड़ताल","निष्पक्षता","स्रोत की सुरक्षा","अफ़वाह से बचना"],"पत्रकार का सबसे बड़ा धर्म सच बताना है। उसे ख़बर छापने से पहले उसकी जाँच-पड़ताल करनी चाहिए और किसी का पक्ष लिए बिना निष्पक्ष रहना चाहिए। अपने सूत्रों की गोपनीयता बनाए रखना भी ज़रूरी है। अफ़वाह या अधूरी जानकारी फैलाने से समाज में भ्रम और तनाव पैदा हो सकता है। इसलिए स्वतंत्रता के साथ ज़िम्मेदारी भी उतनी ही ज़रूरी है।"),
Q("एक अच्छे पत्रकार के दो गुण बताइए।","सत्यनिष्ठा और निष्पक्षता","सोचिए... अच्छा पत्रकार सच की जाँच करता है और किसी का पक्ष नहीं लेता। इन्हीं दो गुणों से उसकी विश्वसनीयता बनती है।"),
C("📱","डिजिटल युग की चुनौतियाँ",["सोशल मीडिया की तेज़ी","फ़ेक न्यूज़","क्लिक के लिए सनसनी","जाँच-पड़ताल की कमी"],"आज सोशल मीडिया पर ख़बरें पल भर में फैल जाती हैं। इससे सूचना का दायरा बढ़ा है, पर झूठी ख़बरें यानी फ़ेक न्यूज़ भी उतनी ही तेज़ी से फैलती हैं। कुछ चैनल और वेबसाइटें ज़्यादा क्लिक पाने के लिए सनसनी फैलाती हैं और सत्यापन की उपेक्षा करती हैं। इस दौर में पाठक और दर्शक को भी सतर्क रहना चाहिए कि ख़बर कहाँ से आई और क्या उसकी पुष्टि हुई।"),
Q("फ़ेक न्यूज़ से बचने के दो तरीक़े बताइए।","स्रोत की जाँच करना और कई विश्वसनीय जगहों पर पुष्टि करना","तरीक़े सोचिए... किसी ख़बर को आगे भेजने से पहले उसका स्रोत देखिए और दूसरे भरोसेमंद अख़बार या चैनल पर पुष्टि कीजिए। बिना जाँचे साझा न करें।"),
C("🧑‍🎓","पाठक की भूमिका और मीडिया साक्षरता",["सवाल पूछना","स्रोत देखना","विविध स्रोत पढ़ना","ज़िम्मेदारी से साझा करना"],"स्वतंत्र प्रेस केवल पत्रकारों का काम नहीं, पाठकों की भी ज़िम्मेदारी है। एक जागरूक पाठक ख़बर पर सवाल उठाता है, अलग-अलग स्रोतों से मिलान करता है और बिना सोचे-समझे उसे फैलाता नहीं। इसे मीडिया साक्षरता कहते हैं। विद्यार्थियों को भी यह कौशल सीखना चाहिए ताकि वे सही और ग़लत जानकारी में फ़र्क़ कर सकें। जागरूक पाठक ही सच्ची स्वतंत्र प्रेस को मज़बूत करते हैं।"),
C("✍️","निबंध और उत्तर के सुझाव",["परिभाषा और महत्व","संवैधानिक स्थिति","दबाव और चुनौतियाँ","सुझाव और निष्कर्ष"],"इस विषय पर निबंध या उत्तर लिखते समय पहले प्रेस की परिभाषा और लोकतंत्र में उसका महत्व बताइए। फिर संविधान की स्थिति लिखिए। उसके बाद दबावों और चुनौतियों की चर्चा कीजिए। अंत में सुझाव लिखिए, जैसे स्वतंत्र मीडिया क़ानून, पत्रकारों की सुरक्षा और मीडिया साक्षरता। अपने शब्दों में और संतुलित भाषा में लिखना अच्छा रहता है।"),
],7)
